const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const scenes=[{id:'product',name:'产品详情页',short:'产品样机',desc:'在真实业务页面中，呈现产品设计',tag:'产品展示',icon:'box',en:'Enterprise networking, reimagined.',detail:'从主图到详情，完整预览产品页面的视觉效果。',position:['主多图','顶部 Banner','详情配图','架构图']},{id:'article',name:'文章配图',short:'文章样机',desc:'还原封面与正文中的视觉表现',tag:'内容设计',icon:'file',en:'Connect ideas. Build what’s next.',detail:'将封面和正文配图放进文章，查看完整阅读体验。',position:['文章封面','正文配图','文章内 Banner']},{id:'social',name:'社媒配图',short:'社媒样机',desc:'在社交媒体中，检验每一份创意',tag:'品牌传播',icon:'image',en:'Designed to keep you connected.',detail:'查看单图或组图在社交信息流中的展示效果。',position:['帖子图片','YouTube 视频封面']},{id:'solution',name:'解决方案',short:'解决方案',desc:'预览方案页面的图文关系',tag:'方案设计',icon:'grid',en:'Smarter networks. Greater possibilities.',detail:'预览方案 Banner、架构图与价值展示。',position:['顶部 Banner','概述','产品架构图','产品清单']},{id:'case',name:'成功案例',short:'案例样机',desc:'让案例成果更直观地呈现',tag:'客户案例',icon:'folder',en:'Real connections. Remarkable outcomes.',detail:'核对案例封面、正文与成果配图。',position:['案例封面','正文配图','架构图','成果配图']}];
