function tools(){return `<div class="tool-grid"><button class="tool-card available" data-action="new"><span class="tool-icon">${icon('box')}</span><span class="badge blue">可使用</span><h3>样机工作台</h3><p>让设计融入真实场景<br>预览、调整，一站式交付</p><div class="tool-bottom"><span>5 类业务场景</span>${icon('arrow')}</div></button><div class="tool-card"><span class="tool-icon purple">${icon('spark')}</span><span class="badge">规划中</span><h3>创意助手</h3><p>从灵感到方案<br>探索设计的更多可能</p><div class="tool-bottom"><span>灵感探索 · 创意延展</span></div></div><div class="tool-card"><span class="tool-icon mint">${icon('folder')}</span><span class="badge">规划中</span><h3>团队知识库</h3><p>沉淀经验与设计规范<br>让团队知识随手可得</p><div class="tool-bottom"><span>设计规范 · 经验沉淀</span></div></div><div class="tool-card"><span class="tool-icon orange">${icon('settings')}</span><span class="badge">规划中</span><h3>效率工具</h3><p>把重复的工作交给工具<br>留出时间，专注创造</p><div class="tool-bottom"><span>批量处理 · 工作流</span></div></div></div>`}
function sideTasks(){$('#sideTasks').innerHTML=saved.length?saved.slice(0,4).map(t=>`<button data-open="${esc(t.id)}">${icon('file')}<span>${esc(t.name)}</span></button>`).join(''):'<div class="side-empty">还没有保存的任务<br>从一份样机开始吧</div>';bindOpen($('#sideTasks'))}
