function taskRows(limit){const list=limit?saved.slice(0,limit):saved;if(!list.length)return `<div class="empty-recent">${icon('clock')}<span>还没有任务，创建你的第一份样机吧</span></div>`;return `<div class="task-table"><div class="task-row head"><div>任务名称</div><span>工具 / 场景</span><span>最近保存</span><div>操作</div></div>${list.map(t=>`<div class="task-row"><div class="task-name"><span class="tool-icon">${icon('box')}</span><div><strong>${esc(t.name)}</strong><small>${t.items.length} 张素材 · 本地保存</small></div></div><span>${esc(scenes.find(s=>s.id===t.scene)?.name||'样机')}</span><span>${new Date(t.updated).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}</span><button class="text-link" data-open="${esc(t.id)}">继续编辑 ${icon('arrow')}</button></div>`).join('')}</div>`}
function home(){return `<div class="page"><section class="welcome"><div class="eyebrow">YOUR IDEAS, CONNECTED.</div><h1>让想法，<span>即刻开始。</span></h1><p class="subtitle">你的团队智能工作台，从一份出色的设计开始。</p><div class="composer"><textarea id="intent" aria-label="描述样机任务" placeholder="今天想完成什么？例如：为新品制作一组产品详情页样机"></textarea><div class="composer-bottom"><div class="composer-meta"><button class="mode-chip" data-action="new">${icon('box')}样机制作 <span>⌄</span></button><span>描述需求，为你定位合适的业务场景</span></div><button class="send" id="sendIntent" aria-label="开始任务">${icon('arrow')}</button></div></div><div class="suggestions"><button data-start="product">${icon('box')}制作产品详情样机</button><button data-start="article">${icon('file')}预览文章配图</button><button data-start="social">${icon('image')}查看社媒展示效果</button></div></section><section><div class="section-heading"><h2>为你的工作，找到合适的工具</h2><a class="text-link" href="#tools">全部工具 ${icon('chevron')}</a></div>${tools()}</section><section class="template-section"><div class="section-heading"><h2>从一个场景开始 <span>选好场景，放入设计，即刻预览</span></h2><a class="text-link" href="#templates">浏览全部模板 ${icon('chevron')}</a></div><div class="template-grid">${scenes.slice(0,3).map(templateCard).join('')}</div></section><section class="recent-section"><div class="section-heading"><h2>继续上次的创作</h2><a class="text-link" href="#tasks">全部任务 ${icon('chevron')}</a></div>${taskRows(2)}</section>${footer()}</div>`}
function bindOpen(root=document){root.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openTask(b.dataset.open))}
function bindCommon(){document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>startTask(b.dataset.start));$$('[data-action="new"]').forEach(b=>b.onclick=chooseTask);bindOpen();if($('#sendIntent')){$('#sendIntent').onclick=submitIntent;$('#intent').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();submitIntent()}}}}
function submitIntent(){const text=$('#intent').value.trim();if(!text){chooseTask();return}const id=/文章|封面|正文/.test(text)?'article':/社媒|帖子|领英|YouTube/i.test(text)?'social':/方案|架构/.test(text)?'solution':/案例/.test(text)?'case':'product';modal('为这次任务选择一个起点',`<p>你的需求：${esc(text)}</p><div class="config-card"><h3>建议使用「${scenes.find(s=>s.id===id).name}」</h3><p>根据关键词定位业务场景，你可以在工作台中随时调整。</p></div><div class="dialog-footer"><button class="primary" id="intentConfirm">开始制作 ${icon('arrow')}</button></div>`);$('#intentConfirm').onclick=()=>{closeModal();startTask(id,text)}}
function chooseTask(){modal('从哪个场景开始？',`<p>选择设计稿将要应用的业务页面。后续可在工作台中切换。</p><div class="template-grid">${scenes.map(templateCard).join('')}</div>`);$('#modalBody').querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>{closeModal();startTask(b.dataset.start)})}
function startTask(id,name){if(dirty){modal('保留当前任务',`<p>当前任务尚未保存。先保存，便于稍后继续编辑。</p><div class="dialog-footer"><button class="secondary" id="discard">放弃当前修改</button><button class="primary" id="saveNew" style="margin-left:8px">保存并新建</button></div>`);$('#discard').onclick=()=>{dirty=false;closeModal();startTask(id,name)};$('#saveNew').onclick=()=>{if(saveTask()){closeModal();startTask(id,name)}};return}currentScene=id;taskName=name||`${scenes.find(s=>s.id===id).name} · 新任务`;taskId=null;items=[];device='desktop';position=scene().position[0];dirty=false;goStudio()}
function goStudio(){if(location.hash==='#studio')render();else location.hash='studio'}
function openTask(id){const t=saved.find(x=>x.id===id);if(!t)return;if(dirty&&location.hash==='#studio'){toast('请先保存当前任务，再切换到其他任务');return}taskId=t.id;currentScene=t.scene;taskName=t.name;items=t.items.map(x=>({...x}));device=t.device||'desktop';position=t.position||scene().position[0];dirty=false;goStudio()}
function templates(){return `<div class="page"><div class="page-title"><div><h1>为设计，找到合适的场景</h1><p>从 5 类业务模板开始，预览设计在真实页面中的样子。</p></div></div><div class="filters"><button class="filter active" data-filter="all">全部场景</button>${scenes.map(s=>`<button class="filter" data-filter="${s.id}">${s.name}</button>`).join('')}<label class="searchbox">${icon('search')}<input id="templateSearch" placeholder="搜索模板" aria-label="搜索模板"></label></div><div class="template-grid" id="templateGrid">${scenes.map(templateCard).join('')}</div><div class="intro-note">模板为交互验证示意。正式版沿用现有平台已核对的业务页面与图片位置规范，模板扩展统一在这里管理。</div>${footer()}</div>`}
function updateTemplates(){const list=scenes.filter(s=>(filter==='all'||s.id===filter)&&s.name.includes(query));$('#templateGrid').innerHTML=list.length?list.map(templateCard).join(''):'<div class="no-results">没有找到匹配的模板，试试其他关键词。</div>';$('#templateGrid').querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>startTask(b.dataset.start))}
function studio(){return `<div class="studio-bar"><div class="studio-name"><a href="#home" class="icon-btn" aria-label="返回工作台">${icon('chevron')}</a><div><input id="taskName" aria-label="任务名称" maxlength="60" value="${esc(taskName)}"><small id="saveStatus">${dirty?'有未保存的修改':taskId?'已保存至当前浏览器':'新任务 · 尚未保存'}</small></div></div><div class="studio-actions"><button class="secondary" id="saveBtn">${icon('folder')}保存任务</button><button class="primary" id="exportBtn" ${items.length?'':'disabled'}>${icon('download')}导出样机</button></div></div><div class="studio-layout"><section class="studio-left"><div class="panel-title">制作样机 <small>简单三步，即刻呈现</small></div><div class="step-label"><span>1</span>选择业务场景</div><select class="select" id="sceneSelect" aria-label="业务场景">${scenes.map(s=>`<option value="${s.id}" ${s.id===currentScene?'selected':''}>${s.name}</option>`).join('')}</select><label class="field-label" for="positionSelect">素材应用位置</label><select class="select" id="positionSelect">${scene().position.map(p=>`<option ${p===position?'selected':''}>${p}</option>`).join('')}</select><div class="divider"></div><div class="step-label"><span>2</span>放入设计素材 <small style="margin-left:auto;color:#a4aec0;font-size:9px" id="imageCount">${items.length} 张</small></div><button class="upload-zone" id="uploadZone">${icon('upload')}<span>点击上传，或将图片拖到这里</span><small>PNG、JPG、WebP · 单张不超过 20 MB</small></button><div id="assetList"></div><p class="upload-hint">图片按原始比例展示，不自动裁切。<br>通过 ↑ ↓ 调整同一位置的图片顺序。</p><div class="divider"></div><div class="step-label"><span>3</span>预览与交付</div><p class="upload-hint">在中间核对图片与页面的关系，<br>确认后导出完整页面用于评审。</p></section><section class="preview-area"><div class="preview-toolbar"><span>页面预览</span><div class="device-toggle"><button data-device="desktop" class="${device==='desktop'?'active':''}">${icon('monitor')}电脑</button><button data-device="phone" class="${device==='phone'?'active':''}">${icon('phone')}手机</button></div><span>适应画布</span></div><div class="preview-scroll"><div class="web-preview ${device==='phone'?'phone':''}" id="webPreview"></div></div><div class="preview-bottom"><i></i><span>示意模板 · 保留素材原始比例 · 不代表真实业务页面</span></div></section><section class="studio-right"><div class="panel-title">交付设置</div><div class="config-card"><h3>${scene().name}</h3><p>${scene().detail}</p></div><div class="config-row"><span>预览设备</span><b>${device==='desktop'?'电脑端':'手机端'}</b></div><div class="config-row"><span>画布宽度</span><b>${device==='desktop'?'1200':'390'} px</b></div><div class="config-row"><span>素材数量</span><b id="rightCount">${items.length} 张</b></div><div class="divider"></div><div class="panel-title">导出格式</div><div class="format-toggle"><button data-format="jpg" class="${format==='jpg'?'active':''}">JPG</button><button data-format="pdf" class="${format==='pdf'?'active':''}">PDF</button></div><button class="primary export-wide" id="exportSide" ${items.length?'':'disabled'}>${icon('download')}导出完整样机</button><div class="save-info">下载至本地 · 不上传设计素材</div><div class="divider"></div><div class="panel-title">交付前检查</div><div class="checklist"><div>${icon('check')}已选择业务场景</div><div class="${items.length?'':'pending'}" id="checkImages">${icon(items.length?'check':'image')}${items.length?'已放入设计素材':'等待上传设计素材'}</div><div>${icon('monitor')}请核对图片位置与展示效果</div></div><p class="studio-note">本版为重设计交互原型。<br>真实页面渲染、在线分享与云端协作沿用后续集成方案。</p></section></div>`}
function markDirty(){dirty=true;if($('#saveStatus'))$('#saveStatus').textContent='有未保存的修改'}
function preview(){const s=scene();const slots=items.length?items.map((x,i)=>`<div class="preview-slot filled"><img src="${x.data}" alt="${esc(x.name)}"></div>`).join(''):`<div class="preview-slot">${icon('image')}<span>${esc(position||s.position[0])} · 等待放入设计</span></div>`;const lines=`<div class="preview-lines">${'<i></i>'.repeat(7)}</div>`;$('#webPreview').innerHTML=`<div class="mini-nav"><b>${currentScene==='social'?'in':'FS'}</b><i></i><i></i><i></i></div><div class="web-breadcrumb">Home　 /　 ${esc(s.tag)}　 /　 Preview</div><div class="web-body">${currentScene==='product'?`<div class="preview-product"><div>${slots}</div><div><h2>Next-generation networking,<br>built for your business.</h2><p class="product-spec">Enterprise performance<br>Reliable connectivity<br>Designed for what’s next</p><div class="price">Product overview</div>${lines}</div></div><div class="mini-tabs" style="padding:18px 0;font-size:9px;gap:25px">Overview <span>Features & specifications</span> Resources</div><h2 style="margin-top:30px;font-size:20px">${s.en}</h2>${lines}`:`${currentScene==='social'?'<div class="mini-user" style="font-size:10px;margin-bottom:18px"><span style="width:28px;height:28px">FS</span><b>FS · Network & Connectivity</b></div>':''}<h2>${s.en}</h2><p class="web-desc">Ideas become real when every detail comes together.<br>Explore a new perspective on connection and possibility.</p>${slots}${lines}<h2 style="font-size:17px;margin-top:28px">Designed to make a difference.</h2>${lines}`}</div>`;renderAssets();$('#exportBtn').disabled=!items.length;$('#exportSide').disabled=!items.length;$('#imageCount').textContent=items.length+' 张';$('#rightCount').textContent=items.length+' 张';$('#checkImages').className=items.length?'':'pending';$('#checkImages').innerHTML=icon(items.length?'check':'image')+(items.length?'已放入设计素材':'等待上传设计素材')}
function renderAssets(){$('#assetList').innerHTML=items.map((x,i)=>`<div class="asset"><img src="${x.data}" alt=""><div class="asset-detail"><b title="${esc(x.name)}">${esc(x.name)}</b><small>${x.width} × ${x.height} · ${esc(position)}</small></div><div class="asset-controls"><button data-up="${i}" ${i===0?'disabled':''} aria-label="上移 ${esc(x.name)}">↑</button><button data-down="${i}" ${i===items.length-1?'disabled':''} aria-label="下移 ${esc(x.name)}">↓</button><button data-remove="${i}" aria-label="移除 ${esc(x.name)}">×</button></div></div>`).join('');$$('[data-up]').forEach(b=>b.onclick=()=>move(+b.dataset.up,-1));$$('[data-down]').forEach(b=>b.onclick=()=>move(+b.dataset.down,1));$$('[data-remove]').forEach(b=>b.onclick=()=>{items.splice(+b.dataset.remove,1);markDirty();preview()})}
function move(i,d){if(i+d<0||i+d>=items.length)return;[items[i],items[i+d]]=[items[i+d],items[i]];markDirty();preview()}
async function addFiles(files){let errors=0;for(const file of files){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>20*1024*1024||items.length>=12){errors++;continue}try{const data=await new Promise((res,rej)=>{const f=new FileReader();f.onload=()=>res(f.result);f.onerror=rej;f.readAsDataURL(file)});const image=new Image();image.src=data;await image.decode();if(image.width*image.height>40000000){errors++;continue}items.push({name:file.name,data,width:image.width,height:image.height});markDirty()}catch{errors++}}preview();if(errors)toast(`${errors} 个文件未添加。仅接受 20 MB 内的图片，每任务最多 12 张、单图最多 4000 万像素。`);else toast('素材已放入样机，可调整顺序并预览')}
$('#fileInput').onchange=async e=>{await addFiles([...e.target.files]);e.target.value=''};
function saveTask(){const name=$('#taskName')?.value.trim()||taskName;const entry={id:taskId||'t'+Date.now().toString(36),name,scene:currentScene,position,device,updated:Date.now(),items:items.map(x=>({...x}))};const next=[entry,...saved.filter(x=>x.id!==entry.id)];try{localStorage.setItem('studio.tasks.v2',JSON.stringify(next));saved=next;taskId=entry.id;taskName=name;dirty=false;if($('#saveStatus'))$('#saveStatus').textContent='已保存至当前浏览器';sideTasks();toast('任务已保存在当前浏览器');return true}catch{toast('浏览器存储空间不足，请减少素材或先导出样机。当前编辑内容仍然保留。');return false}}
function bindStudio(){preview();$('#taskName').oninput=e=>{taskName=e.target.value;markDirty()};$('#sceneSelect').onchange=e=>{currentScene=e.target.value;position=scene().position[0];markDirty();render()};$('#positionSelect').onchange=e=>{position=e.target.value;markDirty();preview()};$('#uploadZone').onclick=()=>$('#fileInput').click();const zone=$('#uploadZone');zone.ondragover=e=>{e.preventDefault();zone.classList.add('dragover')};zone.ondragleave=()=>zone.classList.remove('dragover');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('dragover');addFiles([...e.dataTransfer.files])};$$('[data-device]').forEach(b=>b.onclick=()=>{device=b.dataset.device;markDirty();render()});$$('[data-format]').forEach(b=>b.onclick=()=>{format=b.dataset.format;$$('[data-format]').forEach(x=>x.classList.toggle('active',x.dataset.format===format))});$('#saveBtn').onclick=saveTask;$('#exportBtn').onclick=exportSample;$('#exportSide').onclick=exportSample}
function download(blob,name){const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function makePdf(jpg,w,h){const chunks=[],enc=new TextEncoder();let offset=0;const offsets=[0];const add=s=>{const b=typeof s==='string'?enc.encode(s):s;chunks.push(b);offset+=b.length};add('%PDF-1.4\n');const obj=(n,s)=>{offsets[n]=offset;add(`${n} 0 obj\n${s}\nendobj\n`)};obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>');const pw=600,ph=Math.round(h/w*pw);obj(3,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pw} ${ph}] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>`);offsets[4]=offset;add(`4 0 obj\n<< /Type /XObject /Subtype /Image /Width ${w} /Height ${h} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpg.length} >>\nstream\n`);add(jpg);add('\nendstream\nendobj\n');const content=`q ${pw} 0 0 ${ph} 0 0 cm /Im0 Do Q`;obj(5,`<< /Length ${enc.encode(content).length} >>\nstream\n${content}\nendstream`);const xref=offset;add('xref\n0 6\n0000000000 65535 f \n');for(let i=1;i<=5;i++)add(String(offsets[i]).padStart(10,'0')+' 00000 n \n');add(`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`);return new Blob(chunks,{type:'application/pdf'})}
async function exportSample(){if(!items.length)return;const buttons=[$('#exportBtn'),$('#exportSide')];buttons.forEach(b=>b.disabled=true);try{const w=device==='desktop'?1200:390,pad=Math.round(w*.065),content=w-pad*2;const images=await Promise.all(items.map(async x=>{const im=new Image();im.src=x.data;await im.decode();return im}));const imageW=currentScene==='product'?content*.48:content;const imageHeights=images.map(im=>imageW*im.height/im.width);const total=imageHeights.reduce((a,b)=>a+b+24,0);const h=Math.ceil(320+total+260);if(h>25000)throw Error('too-large');const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const c=canvas.getContext('2d');c.fillStyle='#ffffff';c.fillRect(0,0,w,h);c.fillStyle='#28364d';c.font=`bold ${Math.round(w*.028)}px Arial`;c.fillText(currentScene==='social'?'in':'FS',pad,48);c.fillStyle='#e9edf3';c.fillRect(0,75,w,1);c.fillStyle='#a2adbc';c.font=`${Math.max(10,Math.round(w*.01))}px Arial`;c.fillText('Home  /  '+scene().tag+'  /  Preview',pad,110);c.fillStyle='#344157';c.font=`${Math.max(18,Math.round(w*.03))}px Arial`;c.fillText(currentScene==='product'?'Next-generation networking':scene().en,pad,183,content);c.fillStyle='#98a4b6';c.font=`${Math.max(11,Math.round(w*.013))}px Arial`;c.fillText('Ideas become real when every detail comes together.',pad,222,content);let y=270;images.forEach((im,i)=>{c.drawImage(im,pad,y,imageW,imageHeights[i]);y+=imageHeights[i]+24});if(currentScene==='product'){c.fillStyle='#e9edf4';for(let i=0;i<12;i++)c.fillRect(pad+imageW+35,290+i*25,Math.max(40,content-imageW-35)*(i%3===2?.7:1),6)}c.fillStyle='#edf0f5';for(let i=0;i<6;i++)c.fillRect(pad,y+35+i*22,content*(i%3===2?.75:1),6);c.fillStyle='#a8b2c1';c.font='11px Arial';c.fillText('STUDIO / Preview concept',pad,h-30);const blob=await new Promise(res=>canvas.toBlob(res,'image/jpeg',.93));if(!blob)throw Error('blob');const file=taskName.replace(/[\\/:*?"<>|]/g,'_')||'样机';if(format==='pdf'){const bytes=new Uint8Array(await blob.arrayBuffer());download(makePdf(bytes,w,h),file+'.pdf')}else download(blob,file+'.jpg');toast(`已导出 ${format.toUpperCase()} 示意样机；正式页面样式需接入原有渲染器。`)}catch{toast('本次导出未完成，图片可能过长。请减少图片数量后重试。')}finally{buttons.forEach(b=>b.disabled=false)}}
function help(){modal('让设计落进真实场景',`<p>Studio 是视觉团队的统一工作入口。当前可使用样机工作台，其他工具随部门需求逐步接入。</p><div class="help-steps"><div class="help-step"><span>1</span><div><b>选对场景</b><p>从产品、文章、社媒、解决方案和成功案例中选择，再确认素材应用位置。</p></div></div><div class="help-step"><span>2</span><div><b>放入设计</b><p>支持 PNG、JPG、WebP。上下调整顺序，电脑与手机预览随时切换。</p></div></div><div class="help-step"><span>3</span><div><b>预览并交付</b><p>保存任务后可在此浏览器继续编辑；导出 JPG 或 PDF 可交付给同事查看。</p></div></div></div><div class="intro-note">原型说明：当前提供示意模板与本地任务保存。未连接 AI 模型、团队账号、云端素材或在线分享服务。</div><div class="dialog-footer"><button class="primary" id="helpDone">知道了</button></div>`);$('#helpDone').onclick=closeModal}
function render(){const route=location.hash.slice(1)||'home';const labels={home:'工作台',tools:'工具中心',tasks:'我的任务',templates:'样机模板',studio:'样机工作台'};$('#crumbTitle').textContent=labels[route]||'工作台';$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(route==='studio'?'tools':route)));$('#app').classList.remove('menu-open');if(route==='studio'){$('#main').innerHTML=studio();bindStudio()}else if(route==='templates'){$('#main').innerHTML=templates();filter='all';query='';$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));updateTemplates()});$('#templateSearch').oninput=e=>{query=e.target.value.trim();updateTemplates()}}else if(route==='tools'){$('#main').innerHTML=`<div class="page"><div class="page-title"><div><h1>你的工具，井然有序</h1><p>从高频设计任务开始，逐步连接团队的每一种工作。</p></div></div>${tools()}<div class="intro-note">当前仅开放样机工作台。后续工具的优先级与范围，需要根据团队实际需求确认。</div>${footer()}</div>`}else if(route==='tasks'){$('#main').innerHTML=`<div class="page"><div class="page-title"><div><h1>我的任务</h1><p>保存每次创作的上下文，随时接着完成。</p></div><button class="primary" data-action="new">${icon('plus')}新建任务</button></div>${saved.length?taskRows():`<div class="empty-large">${icon('folder')}<h3>你的下一份创作，从这里开始</h3><p>完成样机后点击“保存任务”，即可在这里继续编辑。</p><button class="primary" data-action="new">创建第一份样机 ${icon('arrow')}</button></div>`}<div class="intro-note">任务与图片保存在当前浏览器，尚未同步到云端。更换浏览器或清除网站数据后无法恢复，请及时导出交付文件。</div>${footer()}</div>`}else{$('#main').innerHTML=home()}bindCommon();sideTasks()}
$('#newTask').onclick=chooseTask;$('#helpBtn').onclick=help;$('#topHelp').onclick=help;$('#spaceBtn').onclick=()=>modal('视觉设计部 · 本地体验空间','<p>这里是部门级工作空间的界面示意。当前任务仅保存在本浏览器。正式版可在此接入团队账号、部门切换与权限管理。</p>');$('#refreshTasks').onclick=()=>{sideTasks();toast('最近任务已刷新')};$('#menuBtn').onclick=()=>$('#app').classList.toggle('menu-open');window.addEventListener('hashchange',render);window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();chooseTask()}});render();
